import{_ as t,o,c as s,a3 as a}from"./chunks/framework.I6s8z2kk.js";const p=JSON.parse('{"title":"API surfaces and guards","description":"","frontmatter":{},"headers":[],"relativePath":"dev/architecture/api-surfaces.md","filePath":"dev/architecture/api-surfaces.md"}'),r={name:"dev/architecture/api-surfaces.md"};function d(c,e,n,i,h,u){return o(),s("div",null,[...e[0]||(e[0]=[a('<h1 id="api-surfaces-and-guards" tabindex="-1">API surfaces and guards <a class="header-anchor" href="#api-surfaces-and-guards" aria-label="Permalink to &quot;API surfaces and guards&quot;">​</a></h1><p>API routes live under <code>/api/v1</code>, except Billing plans and center subscriptions, which are unversioned (<code>/api/admin/*</code>, <code>/api/center/*</code>).</p><table tabindex="0"><thead><tr><th>Surface</th><th>Prefix</th><th>Guard</th><th>Extra middleware</th></tr></thead><tbody><tr><td>Client</td><td><code>clients/*</code></td><td><code>auth:client</code> (some routes are public)</td><td><code>set.locale.from.accept.language</code> on browse routes, <code>track.client.session</code> on authenticated ones</td></tr><tr><td>Center</td><td><code>centers/{center}/*</code></td><td><code>auth:center_user</code></td><td><code>center.scope</code></td></tr><tr><td>Admin</td><td><code>admin/*</code></td><td><code>auth:system_user</code></td><td>Policies check <code>SystemPermission</code></td></tr><tr><td>Shared</td><td><code>media</code>, <code>webhooks/*</code></td><td><code>POST /media</code> accepts several guards; webhooks are public and signature-checked</td><td></td></tr></tbody></table><h2 id="center-scope" tabindex="-1">Center scope <a class="header-anchor" href="#center-scope" aria-label="Permalink to &quot;Center scope&quot;">​</a></h2><p>Every <code>centers/{center}/*</code> route needs <code>center.scope</code>. It requires the token ability <code>center-access:{id}</code> and the center state to be <strong>Active</strong> (only <code>centers.show</code> works otherwise). The middleware does <strong>not</strong> check membership, so controllers must still authorize through <code>CenterPolicy</code>. Issue center tokens only through <code>CenterAuthService::issueCenterAccessToken()</code>.</p><h2 id="admin-mirrors-center" tabindex="-1">Admin mirrors center <a class="header-anchor" href="#admin-mirrors-center" aria-label="Permalink to &quot;Admin mirrors center&quot;">​</a></h2><p>Many admin routes mirror the center ones under <code>admin/centers/{center}/...</code> (services, reservations, purchases, promotions), so staff can act on behalf of a center. They use the same services and policies, which accept both center users and system users.</p><h2 id="docs-sessions" tabindex="-1">Docs sessions <a class="header-anchor" href="#docs-sessions" aria-label="Permalink to &quot;Docs sessions&quot;">​</a></h2><p>API documentation (<code>/docs</code>) and these guides (<code>/guide</code>) use a <strong>session</strong> guard, <code>system_user_web</code>, not a token. It is separate from <code>system_user</code>.</p><h2 id="webhooks" tabindex="-1">Webhooks <a class="header-anchor" href="#webhooks" aria-label="Permalink to &quot;Webhooks&quot;">​</a></h2><p><code>POST /api/v1/webhooks/moyasar</code> and <code>/tamara</code> are idempotent: each event is deduplicated on <code>(gateway, external_event_id)</code>. See <a href="./../domain/purchase">Purchases and payments</a>.</p>',11)])])}const m=t(r,[["render",d]]);export{p as __pageData,m as default};
